import ClipboardJS from "clipboard";
import uploadPictures from "@/components/uploadPictures";
import Setting from '@/setting';

import {
  addConfigApi,
  addStorageApi,
  storageListApi,
  storageSynchApi,
  storageStatusApi,
  editStorageApi,
  getConfigImageApi,
  saveBasicsApi,
  saveType
} from "@/api/setting";
export default {
  name: 'setting_storage',
  components: { uploadPictures },
  data() {
    let isInteger = (rule, value, callback) => {
      if (!value || /(^(-)?[0-9]*$)/.test(value)) {
        callback();
      } else {
        callback(new Error('必须为整数'));
      }
    };
    return {
      baseURL: Setting.apiBaseURL.replace(/adminapi/, ''),
      modalPic: false,
      isChoice: "单选",
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8,
      },
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12,
      },
      configuModal: false,
      configData: "",
      headerList: [
        { label: "基础配置", value: "1" },
        { label: "阿里云储存", value: "3" },
        { label: "腾讯云储存", value: "4" },
        { label: "七牛云储存", value: "2" },
        { label: '京东云储存', value: '5' },
        { label: '华为云储存', value: '6' },
        { label: '天翼云储存', value: '7' },
      ],
      columns: [
        {
          title: "储存空间名称",
          key: "name",
          align: "center",
          minWidth: 200,
        },
        {
          title: "区域",
          key: "_region",
          align: "center",
          minWidth: 100,
        },
        {
          title: "空间域名",
          key: "domain",
          align: "center",
          minWidth: 200,
        },
        {
          title: "使用状态",
          slot: "status",
          align: "center",
          width: 90,
        },
        {
          title: "创建时间",
          key: "_add_time",
          align: "center",
          minWidth: 150,
        },
        {
          title: "更新时间",
          key: "_update_time",
          align: "center",
          minWidth: 150,
        },
        {
          title: "操作",
          slot: "action",
          width: 210,
          align: "center",
        },
      ],
      total: 0,
      list: {
        page: 1,
        limit: 15,
        type: "1",
      },
      levelLists: [],
      currentTab: "1",
      loading: false,
      addData: {
        input: "",
        select: "",
        jurisdiction: "1",
        type: "1",
      },
      confData: {
        AccessKeyId: "",
        AccessKeySecret: "",
      },
      formData: {
        upload_type: 1,
        image_watermark_status: 0,
        image_thumb_status: 0,
        thumb_big_width: '',
        thumb_big_height: '',
        thumb_mid_width: '',
        thumb_mid_height: '',
        thumb_small_width: '',
        thumb_small_height: '',
        watermark_type: 1,
        watermark_text: '',
        watermark_text_angle: '',
        watermark_text_color: '',
        watermark_text_size: '',
        watermark_position: 1,
        watermark_image: '',
        watermark_opacity: '',
        watermark_rotate: '',
        watermark_x: '',
        watermark_y: ''
      },
      rules: {
        thumb_big_width: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ],
        thumb_big_height: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ],
        thumb_mid_width: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ],
        thumb_mid_height: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ],
        thumb_small_width: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ],
        thumb_small_height: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ],
        watermark_x: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ],
        watermark_y: [
          {
            validator: isInteger,
            trigger: 'blur'
          }
        ]
      },
      visible: false
    };
  },
  computed: {
    positionText() {
      return ['左上', '中上', '右上', '左中', '中', '右中', '左下', '中下', '右下'][this.formData.watermark_position - 1];
    }
  },
  created() {
    this.getConfigImage();
  },
  mounted: function () {
    // this.$nextTick(function () {
    //   const clipboard = new ClipboardJS(".copy-data");
    //   clipboard.on("success", () => {
    //     this.$Message.success("复制成功");
    //   });
    // });
  },
  methods: {
    onCopy() {
      this.$Message.success("复制成功");
    },
    onError() {
      this.$Message.error("复制失败");
    },
    changeSave(type) {
      saveType(type)
        .then((res) => {
          this.$Message.success(res.msg);
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    //   获取缩略图配置
    getConfigImage() {
      getConfigImageApi().then(res => {
        let data = res.data;
        this.formData.upload_type = parseInt(data.upload_type.value);
        this.formData.image_watermark_status = data.image_watermark_status.value;
        this.formData.image_thumb_status = data.image_thumb_status.value;
        this.formData.thumb_big_width = data.thumb_big_width.value;
        this.formData.thumb_big_height = data.thumb_big_height.value;
        this.formData.thumb_mid_width = data.thumb_mid_width.value;
        this.formData.thumb_mid_height = data.thumb_mid_height.value;
        this.formData.thumb_small_width = data.thumb_small_width.value;
        this.formData.thumb_small_height = data.thumb_small_height.value;
        this.formData.watermark_type = data.watermark_type.value;
        this.formData.watermark_text = data.watermark_text.value;
        this.formData.watermark_text_angle = data.watermark_text_angle.value;
        this.formData.watermark_text_color = data.watermark_text_color.value;
        this.formData.watermark_text_size = data.watermark_text_size.value;
        this.formData.watermark_position = data.watermark_position.value;
        this.formData.watermark_image = data.watermark_image.value;
        this.formData.watermark_opacity = data.watermark_opacity.value;
        this.formData.watermark_rotate = data.watermark_rotate.value;
        this.formData.watermark_x = data.watermark_x.value;
        this.formData.watermark_y = data.watermark_y.value;
      });
    },
    //   基础配置保存
    handleSubmit(name) {
      this.$refs[name].validate(valid => {
        if (valid) {
          saveBasicsApi(this.formData).then(res => {
            this.$Message.success(res.msg);
          }).catch(res => {
            this.$Message.error(res.msg);
          });
        }
      });
    },
    // 选择图片
    modalPicTap() {
      this.modalPic = true;
    },
    // 选中图片
    getPic(pc) {
      this.formData.watermark_image = pc.att_dir;
      this.modalPic = false;
    },
    // CNAME配置
    config(row) {
      this.configuModal = true;
      this.configData = row;
    },
    //同步储存空间
    synchro() {
      storageSynchApi(this.currentTab)
        .then((res) => {
          this.$Message.success(res.msg);
          this.getlist();
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    // 添加存储空间
    addStorageBtn() {
      this.$modalForm(addStorageApi(this.currentTab)).then(() => {
        this.getlist();
      });
    },
    // 修改配置信息
    addConfigBtn() {
      this.$modalForm(addConfigApi(this.currentTab)).then(() => {
        this.getlist();
      });
    },
    //修改空间域名
    edit(row) {
      this.$modalForm(editStorageApi(row.id)).then(() => {
        this.getlist();
      });
    },
    // 使用状态
    changeSwitch(row, item) {
      return new Promise((resolve) => {
        this.$Modal.confirm({
          title: "切换状态",
          content: "您确认要切换使用状态吗？",
          onOk: () => {
            // resolve();
            storageStatusApi(row.id)
              .then((res) => {
                this.$Message.success(res.msg);
                this.getlist();
              })
              .catch((err) => {
                this.$Message.error(err.msg);
              });
          },
          onCancel: () => {
            this.$Message.info("已取消");
            this.getlist();
          },
        });
      });
    },
    // 云存储列表
    getlist() {
      this.loading = true;
      storageListApi(this.list).then((res) => {
        this.total = res.data.count;
        this.levelLists = res.data.list;
        this.loading = false;
      });
    },
    // 切换选项卡
    changeTab(data) {
      this.currentTab = data;
      this.list.type = data;
      this.list.page = 1;
      if (data == 1) {
        this.getConfigImage();
      } else {
        this.getlist();
      }
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `setting/config/storage/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.getlist();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    pageChange(index) {
      this.list.page = index;
      this.getlist();
    },
    handleView() {
      this.visible = true;
    },
    handleRemove() {
      this.formData.watermark_image = '';
    }
  },
};
